%[text] # Vehicle1DPerformanceParameters sample script
data = Vehicle1DPerformanceParameters;
%[text] Set the car specs.
% Medium car spec
data.TireRollingCoefficient = simscape.Value(0.0136, "1");
data.VehicleMass = simscape.Value(1800, "kg");
data.AirDragCoefficient = simscape.Value(0.31, "1");
data.FrontalArea = simscape.Value(2.36, "m^2");
data.TopSpeed = simscape.Value(160, "km/hr");
data.MaximumAcceleration = simscape.Value(0.4, "1");
data.MaximumClimbGrade = simscape.Value(5, "1");
%[text] Make sure to update the derived parameters.
data = update_states(data);
disp(data) %[output:2fcf876f]
%[text] Use the data, for example, to create the longitudinal performance plot.
Vehicle1DPerformancePlot( ... %[output:group:726b2ff4] %[output:057fbdc1]
  VehicleMass = data.VehicleMass, ... %[output:057fbdc1]
  GravitationalAcceleration = data.GravitationalAcceleration, ... %[output:057fbdc1]
  RoadLoadA = data.RoadLoadA, ... %[output:057fbdc1]
  RoadLoadB = data.RoadLoadB, ... %[output:057fbdc1]
  RoadLoadC = data.RoadLoadC, ... %[output:057fbdc1]
  TopSpeed = data.TopSpeed, ... %[output:057fbdc1]
  MaximumAcceleration = data.MaximumAcceleration, ... %[output:057fbdc1]
  MaximumClimbPower = data.MaximumClimbPower, ... %[output:057fbdc1]
  PlotGrades = data.PlotGrades, ... %[output:057fbdc1]
  PlotPowers = data.PlotPowers, ... %[output:057fbdc1]
  PlotForceUpperBound = data.PlotForceUpperBound, ... %[output:057fbdc1]
  PlotForceUnit = data.PlotForceUnit, ... %[output:057fbdc1]
  PlotSpeedUpperBound = data.PlotSpeedUpperBound, ... %[output:057fbdc1]
  PlotSpeedUnit = data.PlotSpeedUnit ); %[output:group:726b2ff4] %[output:057fbdc1]
